catalog_script_client.script:
var fieldArray = ['subject_common_name', 'subject_alternative_name', 'organization', 'organizational_unit', 'province', 'locality', 'country', 'email'];
var csrAttributesFromCatalogForm;

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading)
        return;

	if(!(g_user.hasRole('sn_disco_certmgmt.pki_admin') || g_user.hasRole('sn_disco_certmgmt.pki_user') || g_user.hasRole('sn_disco_certmgmt.certificate_requester'))) {
		g_form.addErrorMessage("User is not authorized. User doesn't contain proper roles (pki_admin, pki_user, certificate_requester)");
		return;
	}

    if (newValue == "") {
        setCatalogFormFieldsValue(csrAttributesFromCatalogForm);
        return;
    }
    csrAttributesFromCatalogForm = getCSRAttributesFromCatalogForm();
    var ga = new GlideAjax("global.CSRDecodeCertificateAjax");
    ga.addParam("sysparm_name", "getSubjectAttributesFromCSR");
    ga.addParam('sysparm_CSRString', newValue);
    ga.getXML(ajaxResponse);
}

function ajaxResponse(response) {
    var csrAttrsResult = response.responseXML.documentElement.getAttribute("answer");
    var csrAttrsInfo = (csrAttrsResult) ? JSON.parse(csrAttrsResult) : '';
    setCatalogFormFieldsValue(csrAttrsInfo);
    if (!csrAttrsInfo)
        g_form.showFieldMsg('csr', getMessage('Invalid CSR'), 'error');
}

function hexToIPv4(hex) {
    var parts = [];
    for (var i = 0; i < 8; i += 2) {
        parts.push(parseInt(hex.substring(i, i + 2), 16));
    }
    return parts.join('.');
}

function hexToIPv6(hex) {
    var parts = [];
    for (var i = 0; i < 32; i += 4) {
        var group = hex.substring(i, i + 4).toLowerCase();
        group = group.replace(/^0+/, '');
        parts.push(group === '' ? '0' : group);
    }
    return parts.join(':');
}

function setCatalogFormFieldsValue(csrAttrs) {
    fieldArray.forEach(function(field) {
        if(field == 'subject_alternative_name' && csrAttrs && csrAttrs['subject_alternative_name'])
        {
            var newSAN = csrAttrs['subject_alternative_name'];
            var regex = /(?:\d+:\s+)?#([a-fA-F0-9\s]{8,})/g;
            newSAN = newSAN.replace(regex, function(match, hexWithSpaces) {
                var hex = (hexWithSpaces || '').replace(/\s+/g, '');
                if (hex.length === 8) {
                    return hexToIPv4(hex);
                } else if (hex.length === 32) {
                    return hexToIPv6(hex);
                }
                return match;
            });
            csrAttrs['subject_alternative_name'] = newSAN;
        }
        g_form.setValue(field, (csrAttrs) ? csrAttrs[field] : '');
    });
}

function getCSRAttributesFromCatalogForm() {
    var csrAttrObj = {};
    fieldArray.forEach(function(field) {
        csrAttrObj[field] = g_form.getValue(field);
    });
    return csrAttrObj;
}
